view.renderReportDialog:
function renderReportDialog(opts) {
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  // Character-level LCS — produces the smallest possible diff so users
  // see EXACTLY which chars changed. Removing a trailing comma shows
  // just the comma struck through; one-letter swap (effected→affected)
  // shows just "e→a". Word-level diff (v2's approach) would strike out
  // entire words for tiny edits, which obscures what actually changed.
  // O(m*n) — fine for paragraph excerpts (~200 chars × 200 chars).
  function _wordDiff(oldText, newText) {
    if (!oldText) oldText = "";
    if (!newText) newText = "";
    var a = String(oldText), b = String(newText);
    var m = a.length, n = b.length;
    var dp = [];
    for (var i = 0; i <= m; i++) dp.push(new Array(n + 1).fill(0));
    for (var i = 1; i <= m; i++) {
      for (var j = 1; j <= n; j++) {
        if (a.charAt(i - 1) === b.charAt(j - 1)) dp[i][j] = dp[i - 1][j - 1] + 1;
        else dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
    // Backtrack — parts: { value: <chars>, added?, removed? }
    var parts = [];
    var ii = m, jj = n;
    while (ii > 0 || jj > 0) {
      if (ii > 0 && jj > 0 && a.charAt(ii - 1) === b.charAt(jj - 1)) {
        var last = parts[0];
        if (last && !last.added && !last.removed) last.value = a.charAt(ii - 1) + last.value;
        else parts.unshift({ value: a.charAt(ii - 1) });
        ii--; jj--;
      } else if (jj > 0 && (ii === 0 || dp[ii][jj - 1] >= dp[ii - 1][jj])) {
        var lastA = parts[0];
        if (lastA && lastA.added) lastA.value = b.charAt(jj - 1) + lastA.value;
        else parts.unshift({ value: b.charAt(jj - 1), added: true });
        jj--;
      } else if (ii > 0) {
        var lastR = parts[0];
        if (lastR && lastR.removed) lastR.value = a.charAt(ii - 1) + lastR.value;
        else parts.unshift({ value: a.charAt(ii - 1), removed: true });
        ii--;
      }
    }
    // Fold into hunks — equal runs as one hunk; consecutive add/remove
    // parts merge into a single change hunk with both old and new strings.
    var hunks = [];
    var current = null;
    parts.forEach(function (p) {
      if (!p.added && !p.removed) {
        if (current) { hunks.push(current); current = null; }
        hunks.push({ type: "equal", text: p.value });
      } else {
        if (!current) current = { type: "change", oldText: "", newText: "" };
        if (p.removed) current.oldText += p.value;
        if (p.added)   current.newText += p.value;
