  // correctly regardless of CSS panel staleness. Equal text plain,
  // deletion red strikethrough, addition blue bold.
  // V2 _eliNormalizeSearchText (taskpane_v2.js:32795) — used by _patchText so
  // the AI's needle (which often has curly quotes) matches doc text.
  function _normalizeSearchText(s) {
    if (s == null) return s;
    return String(s)
      .replace(/[“”]/g, '"')
      .replace(/[‘’]/g, "'")
      .replace(/[–—]/g, "-")
      .replace(/ /g, " ");
