  // V2 _eliPatchText (taskpane_v2.js:32799) — replace `needle` with
  // `replacement` in `haystack`, normalizing curly quotes / dashes / NBSP
  // when the literal index lookup fails. Returns null if needle not found.
  function _patchText(haystack, needle, replacement) {
