        '<label id="_eli3_er_redline_toggle" style="display:inline-flex;align-items:center;gap:6px;padding:5px 10px;background:rgba(255,255,255,0.15);border:1px solid rgba(255,255,255,0.3);cursor:pointer;font-size:10px;font-weight:700;color:#fff;text-transform:uppercase;letter-spacing:0.5px;user-select:none;white-space:nowrap">' +
          '<input type="checkbox" id="_eli3_er_redline_chk" style="margin:0;cursor:pointer;accent-color:#c9a227">' +
          '<span>Apply with redlines</span>' +
        '</label>' +
        '<div class="erb-count-box">' +
          '<div class="erb-count">' + items.length + '</div>' +
          '<div class="erb-count-label">found</div>' +
        '</div>' +
      '</div>';
  var headerHtml =
    '<div class="error-result-banner">' +
      '<div style="position:relative;z-index:2">' +
        '<div class="erb-label">' + (items.length === 0 ? "ALL CLEAR" : "EDITS FOUND") + '</div>' +
        '<div class="erb-title">' + (items.length === 0 ? "No Errors Found" : "Suggested Fixes") + '</div>' +
      '</div>' +
