  }
  function _searchWithFallback(range, needle, context) {
    if (!needle) return Promise.resolve(null);
    var direct = range.search(needle, { matchCase: false });
    direct.load("items");
    return context.sync().then(function () {
      if (direct.items.length > 0) return direct.items[0];
      var alt = _normalizeSearchText(needle);
      if (alt !== needle) {
        var s2 = range.search(alt, { matchCase: false });
        s2.load("items");
        return context.sync().then(function () {
          if (s2.items.length > 0) return s2.items[0];
          return _wsFlexStep();
        });
      }
      return _wsFlexStep();
    });
    function _wsFlexStep() {
      if (!/\s/.test(needle)) return _gapStep();
      var wsNeedle = _makeWhitespaceFlexibleNeedle(needle);
      if (!wsNeedle || wsNeedle === needle) return _gapStep();
      try {
        var s3 = range.search(wsNeedle, { matchCase: false, matchWildcards: true });
        s3.load("items");
        return context.sync().then(function () {
          if (s3.items.length > 0) return s3.items[0];
          return _gapStep();
        }).catch(function () { return _gapStep(); });
      } catch (e) { return _gapStep(); }
    }
    function _gapStep() {
      var gapNeedle = _makeGapTolerantNeedle(needle);
      if (!gapNeedle) return null;
      try {
        var s4 = range.search(gapNeedle, { matchCase: false, matchWildcards: true });
        s4.load("items");
        return context.sync().then(function () {
          return s4.items.length > 0 ? s4.items[0] : null;
        }).catch(function () { return null; });
      } catch (e) { return null; }
    }
  }

  // ── Minimal-diff apply helpers (v2 parity) ──────────────────────────
  // Ported from taskpane_v2.js lines 32928-33117. The point of this whole
  // pipeline: when the AI returns "X means" → "X. means" (just adding a
  // period), we want to insert ONE character at the right spot — not
  // replace the whole bookmarked phrase, which would wipe italic/bold/font
  // formatting on the rest of the substring. Path:
  //   1. _isMinorEdit  — refuse fixes whose length deviates absurdly
  //   2. _computeMinimalDiff — strip common prefix/suffix
  //   3. _captureFont / _applyFont — preserve formatting
  //   4. _expandUntilUnique — find a unique anchor when oldMid repeats
  //   5. _applyMinimalDiff — orchestrate insert/replace at narrowest scope
  function _isMinorEdit(original, correction) {
    if (original == null || correction == null) return true;
    var oLen = String(original).length;
    var cLen = String(correction).length;
    var diff = Math.abs(oLen - cLen);
    var allowed = Math.max(20, Math.floor(oLen * 0.5));
    return diff <= allowed;
  }
  function _captureFont(range, context) {
    range.font.load("italic, bold, underline, color, name, size, highlightColor");
    return context.sync().then(function () {
      return {
        italic: range.font.italic,
        bold: range.font.bold,
        underline: range.font.underline,
        color: range.font.color,
        name: range.font.name,
        size: range.font.size,
        highlightColor: range.font.highlightColor,
      };
    });
  }
  function _applyFont(range, snap) {
    if (!snap) return;
    function setSafe(prop, val, ok) {
      if (val == null) return;
      if (ok && !ok(val)) return;
      try { range.font[prop] = val; } catch (e) { /* tolerate */ }
    }
    var isBool = function (v) { return typeof v === "boolean"; };
    var isStr  = function (v) { return typeof v === "string" && v.length > 0; };
    var isPos  = function (v) { return typeof v === "number" && v > 0; };
    setSafe("italic", snap.italic, isBool);
    setSafe("bold", snap.bold, isBool);
    setSafe("underline", snap.underline, isBool);
    setSafe("color", snap.color, isStr);
    setSafe("name", snap.name, isStr);
    setSafe("size", snap.size, isPos);
    setSafe("highlightColor", snap.highlightColor, isStr);
  }
  function _computeMinimalDiff(original, correction) {
    var o = String(original || ""), c = String(correction || "");
    var pLen = 0, maxP = Math.min(o.length, c.length);
    while (pLen < maxP && o.charCodeAt(pLen) === c.charCodeAt(pLen)) pLen++;
    var sLen = 0, maxS = Math.min(o.length - pLen, c.length - pLen);
    while (sLen < maxS && o.charCodeAt(o.length - 1 - sLen) === c.charCodeAt(c.length - 1 - sLen)) sLen++;
    return {
      prefix: o.slice(0, pLen),
      oldMid: o.slice(pLen, o.length - sLen),
      newMid: c.slice(pLen, c.length - sLen),
      suffix: o.slice(o.length - sLen),
    };
  }
  function _escapeRegex(s) {
    return String(s).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  }
  function _expandUntilUnique(haystack, prefix, oldMid, newMid, suffix) {
    function countMatches(needle) {
      if (!needle) return 0;
      return (haystack.match(new RegExp(_escapeRegex(needle), "g")) || []).length;
    }
    var pBefore = 0, pAfter = 0;
    if (countMatches(oldMid) === 1) {
      return { searchOld: oldMid, searchNew: newMid };
    }
    var maxBefore = prefix.length, maxAfter = suffix.length;
    while (pBefore < maxBefore || pAfter < maxAfter) {
      if (pBefore < maxBefore) pBefore++;
      var so = prefix.slice(prefix.length - pBefore) + oldMid + suffix.slice(0, pAfter);
      var sn = prefix.slice(prefix.length - pBefore) + newMid + suffix.slice(0, pAfter);
      if (countMatches(so) === 1) return { searchOld: so, searchNew: sn };
      if (pAfter < maxAfter) pAfter++;
      var so2 = prefix.slice(prefix.length - pBefore) + oldMid + suffix.slice(0, pAfter);
      var sn2 = prefix.slice(prefix.length - pBefore) + newMid + suffix.slice(0, pAfter);
      if (countMatches(so2) === 1) return { searchOld: so2, searchNew: sn2 };
    }
    return null;
  }
  function _applyMinimalDiff(range, original, correction, context) {
    var diff = _computeMinimalDiff(original, correction);
    if (diff.oldMid === "" && diff.newMid === "") return Promise.resolve(true);
    // Pure insertion (oldMid is empty) — insert newMid at the right edge.
    if (diff.oldMid === "") {
      if (!diff.prefix && !diff.suffix) {
        range.insertText(diff.newMid, "Replace");
        return Promise.resolve(true);
      }
      if (!diff.suffix) { range.insertText(diff.newMid, "End"); return Promise.resolve(true); }
      if (!diff.prefix) { range.insertText(diff.newMid, "Start"); return Promise.resolve(true); }
      var pSearch = range.search(diff.prefix, { matchCase: true });
      pSearch.load("items");
      return context.sync().then(function () {
        if (pSearch.items.length > 0) {
          pSearch.items[0].insertText(diff.newMid, "After");
          return true;
        }
        range.insertText(correction, "Replace");
        return true;
      });
    }
    // Substitution path — find the narrowest unique anchor inside the
    // bookmarked range, snapshot its font, replace, restore font.
    range.load("text");
    return context.sync().then(function () {
      var rangeText = range.text || "";
      var found = _expandUntilUnique(rangeText, diff.prefix, diff.oldMid, diff.newMid, diff.suffix);
      if (!found) {
        range.insertText(correction, "Replace");
        return true;
      }
      var subSearch = range.search(found.searchOld, { matchCase: true });
      subSearch.load("items");
      return context.sync().then(function () {
        if (subSearch.items.length === 0) {
          range.insertText(correction, "Replace");
          return true;
        }
        var oldSub = subSearch.items[0];
        return _captureFont(oldSub, context).then(function (snap) {
          var newSub = found.searchNew === ""
            ? oldSub.insertText("", "Replace")
            : oldSub.insertText(found.searchNew, "Replace");
          if (newSub) _applyFont(newSub, snap);
          return true;
        });
      });
    });
  }

  // ── Accept handler ──────────────────────────────────────────────────
  // V2 parity (taskpane_v2.js:33153+ hybridApplyError). Sequence:
  //   1. _isMinorEdit guard — refuse oversized rewrites
  //   2. set changeTrackingMode based on user's redline toggle
  //   3. resolve the bookmark; if precision=paragraph, narrow via search
  //   4. _applyMinimalDiff for prefix/suffix-aware replace + font preserve
  function _acceptOne(item) {
    if (!_isMinorEdit(item.original, item.correction)) {
      var ToolErr = window.eli && window.eli.errors && window.eli.errors.ToolError || Error;
      return Promise.reject(new ToolErr(
        "Refused — fix size doesn't match error size (possible AI rewrite). Use Locate and edit manually."
      ));
    }
    return eli.host.runRaw("error_review:accept", function (context) {
      var phrase = (item.original || "").trim();
      var fix = item.correction || "";
      if (!phrase) {
        var ToolErr2 = window.eli && window.eli.errors && window.eli.errors.ToolError || Error;
        throw new ToolErr2("Empty 'original' — can't replace.");
      }
      var shouldTrack = !!window._eliApplyWithRedlines;
      try {
        context.document.changeTrackingMode = shouldTrack ? "TrackAll" : "Off";
      } catch (toggleErr) { /* tolerate — older Word builds may throw */ }

      var bk = item._errBookmark || item.id;
      if (!bk) {
        return context.sync().then(function () { return _bodySearchReplace(context, phrase, fix); });
      }
      var range = context.document.getBookmarkRangeOrNullObject(bk);
      range.load("isNullObject");
      return context.sync().then(function () {
        if (range.isNullObject) {
          return _bodySearchReplace(context, phrase, fix);
        }
        if (item._precision === "exact") {
          // Bookmark IS the exact error range — minimal-diff replace
          // preserves font/format on the unchanged prefix/suffix chars.
          return _applyMinimalDiff(range, phrase, fix, context).then(function () {
            return context.sync();
          });
        }
        // Paragraph precision — narrow with v2's _eliSearchWithFallback
        // (4-strategy wildcard cascade), then minimal-diff on the result.
        return _searchWithFallback(range, phrase, context).then(function (sub) {
          if (!sub) {
            // Fall through to body-wide as last resort. v2 returned
            // "couldn't pinpoint" here; v3 keeps the more-forgiving path.
            return _bodySearchReplace(context, phrase, fix);
          }
          return _applyMinimalDiff(sub, phrase, fix, context)
            .then(function () { return context.sync(); });
        });
      });
    });
  }
  function _bodySearchReplace(context, phrase, fix) {
    // Last resort — bookmark missing AND in-paragraph search failed.
    // Same variant cascade as _bodySearchSelect.
    var variants = _searchVariants(phrase);
    var searches = variants.map(function (v) {
      return _trySearchInRange(context.document.body, v);
    });
    return context.sync().then(function () {
      for (var i = 0; i < searches.length; i++) {
        if (searches[i].items.length > 0) {
          return _applyMinimalDiff(searches[i].items[0], phrase, fix, context)
            .then(function () { return context.sync(); });
        }
      }
      var ToolErr3 = window.eli && window.eli.errors && window.eli.errors.ToolError || Error;
      throw new ToolErr3("Couldn't find '" + phrase + "' in document.");
    });
  }

  // ── Scan flow ────────────────────────────────────────────────────────
  function _runScan(settings) {
    var mount = document.getElementById("_eli3_dashboard_root");

    function _safeTransition(target) {
      try { eli.fsm.transition(target); }
      catch (e) { /* tolerate */ }
    }
    function _goHome() {
      if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
      else if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
    }

    _safeTransition("scanning");
    // Cancel token threaded into eli.ai so a user-clicked cancel button
    // aborts the in-flight AI request rather than just dismissing UI.
    var cancelToken = (eli.cancel && typeof eli.cancel.token === "function")
      ? eli.cancel.token()
      : null;
    var overlay = renderProgressOverlay({
      onCancel: function () {
        // Abort the AI request mid-flight. The analyze().catch handler
        // below tears down the overlay + transitions back to idle.
        if (cancelToken && typeof cancelToken.abort === "function") {
          try { cancelToken.abort(); } catch (e) { /* tolerate */ }
        }
      },
    });
    var providers = { host: eli.host, ai: eli.ai, storage: eli.storage };
    var input = {
      settings: settings,
      onLog: overlay.log,
      docHash: null,
      // Engine forwards this signal into eli.ai.completeJSON's opts.signal.
      signal: cancelToken && cancelToken.signal,
    };

    function _afterAnalyze(result) {
      try {
        if (eli.stats) {
          eli.stats.record("appOpenedError");
          eli.stats.record("docsReviewed");
          eli.stats.record("errorsScanned");
          if (result.items && result.items.length) {
            eli.stats.record("errorsFound", result.items.length);
          }
        }
        if (eli.activity) {
          var summary = result.items.length === 0
            ? "✅ No errors found"
            : result.items.length + " issue(s) detected";
          // Store the full result so the session-feed click handler can
          // restore the report later. Strip wrongness-style raw doc text
          // since result already only contains AI-derived data; nothing
          // sensitive to redact here.
          eli.activity.add({
            type: "error_review",
            icon: "🔍",
            label: "Error Review",
            summary: summary,
            payload: result,
            // Tells the kernel feed-click handler which channel/key to
            // dispatch. Tool registers an activity_restore handler below.
            restoreChannel: "activity_restore",
            restoreKey: "error_review",
          });
        }
        if (eli.wrongness) eli.wrongness.capture("error_review", input, result, {});
      } catch (sideErr) {
        eli.log.event("tool", "error_review_side_effects_failed", {
          error: sideErr && sideErr.message,
        });
      }
      _safeTransition("rendering");
      renderReportDialog({
        result: result,
        mount: mount,
        onLocate: _locate,
        onAcceptOne: _acceptOne,
        onClose: function () {
          _safeTransition("idle");
          _goHome();
        },
      });
    }

    analyze(input, providers).then(function (result) {
      overlay.close();
      try {
        _afterAnalyze(result);
      } catch (renderErr) {
        eli.log.event("tool", "error_review_render_failed", {
          error: renderErr && renderErr.message,
          stack: (renderErr && renderErr.stack || "").slice(0, 500),
        });
        if (typeof showToast === "function") {
          showToast("Report render failed: " + (renderErr && renderErr.message || "unknown"), "err");
        }
        _goHome();
        _safeTransition("error");
        setTimeout(function () { try { eli.fsm.transition("idle"); } catch (e) {} }, 100);
      }
    }).catch(function (err) {
      overlay.close();
      _goHome();
      _safeTransition("error");
      if (typeof showToast === "function") {
        showToast("Scan failed: " + (err && err.message || "unknown"), "err");
      }
      eli.log.event("tool", "error_review_failed", { error: err && err.message });
      setTimeout(function () { try { eli.fsm.transition("idle"); } catch (e) {} }, 100);
    });
  }

  // ── Tile handler (main click) ────────────────────────────────────────
  // Direct path: API-key check → redlines warn → scope detect → scan.
  // No settings dialog. Settings live behind the gear icon.
  function tileHandler() {
    if (!eli.ai || !eli.ai.hasApiKey()) {
      if (typeof showToast === "function") {
        showToast("Set a Gemini API key in Settings → Global first.", "warn");
      }
      // Open settings as a courtesy so the user can fix it.
      if (eli.settings && eli.settings.show) eli.settings.show();
      return;
    }

    var saved = _readUserSettings();
    var sensitivity = saved.sensitivity || "Balanced";

    // Pre-scan: redlines warning, then selection-scope decision.
    _checkRedlines().then(function (proceed) {
      if (!proceed) return;
      _detectScope().then(function (initial) {
        if (initial === "askUser") {
          _askScope().then(function (scope) {
            if (!scope) return; // user cancelled
            _runScan({ sensitivity: sensitivity, scope: scope });
          });
        } else {
          _runScan({ sensitivity: sensitivity, scope: "full" });
        }
      });
    });
  }

  // ── Gear handler (settings) ──────────────────────────────────────────
  // Opens the sensitivity picker. Settings persist on Save (closing the
  // dialog with Save). Cancel just dismisses.
  function gearHandler() {
    var saved = _readUserSettings();
    var hasApiKey = !!(eli.ai && eli.ai.hasApiKey());
    var mount = document.getElementById("_eli3_dashboard_root");
    renderSettingsDialog({
      hasApiKey: hasApiKey,
      sensitivity: saved.sensitivity || "Balanced",
      mount: mount,
      gearMode: true, // tells the view to render Save/Cancel instead of Scan/Home
    }).then(function (settings) {
      if (settings) {
        var s = _readUserSettings();
        s.sensitivity = settings.sensitivity;
        _writeUserSettings(s);
        if (typeof showToast === "function") {
          showToast("Saved: sensitivity " + settings.sensitivity, "ok");
        }
      }
      if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
    });
  }

  // Register all three channels:
  //   tile             — main click runs scan
  //   tile_settings    — gear icon opens sensitivity picker
  //   activity_restore — feed-item click re-renders the saved report
  eli.register({
    tile: { "app_error_review": tileHandler },
    tile_settings: { "app_error_review": gearHandler },
    activity_restore: {
      "error_review": function (payload) {
        var mount = document.getElementById("_eli3_dashboard_root");
        if (!mount || !payload) return;
        // Re-show the report panel using the saved result. FSM goes to
        // rendering on entry; idle on close (same as a fresh scan).
        try { eli.fsm.transition("rendering"); } catch (e) { /* tolerate */ }
        renderReportDialog({
          result: payload,
          mount: mount,
          onLocate: _locate,
          onAcceptOne: _acceptOne,
          onClose: function () {
            try { eli.fsm.transition("idle"); } catch (e) { /* tolerate */ }
            if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
          },
        });
      },
    },
  });
  eli.log.event("tool", "error_review_initialized", {});
}
